/** Synthetic provider-shaped image; contains no real enrollment material. */
export function denseAuthenticatorSvg(cells = 57) {
  const size = (cells + 8) * 3;
  const rectangles = [];
  for (let y = 0; y < cells; y++) {
    for (let x = 0; x < cells; x++) {
      const color = (x + y) % 2 ? "black" : "white";
      rectangles.push(`<rect x="${12 + x * 3}" y="${12 + y * 3}" width="3" height="3" style="fill:${color};stroke:none"/>`);
    }
  }
  return `<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">\n${rectangles.join("\n")}\n</svg>`;
}
